create or replace function public.operator_service_upsert_location(p_actor_user_id uuid,p_company_id uuid,p_location_id uuid default null,p_location_code text default null,p_name text default null,p_address text default null,p_city text default null,p_state text default null,p_postal text default null,p_market text default null,p_area text default null,p_request_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path to '' as $function$ declare v_id uuid;v_count integer; begin if not exists(select 1 from private.platform_operators where user_id=p_actor_user_id and active=true and operator_role='platform_admin') then raise exception 'Platform administrator access required'; end if; if not exists(select 1 from public.companies where id=p_company_id) then raise exception 'Customer not found'; end if; if nullif(btrim(p_location_code),'') is null then raise exception 'Location code is required'; end if; if nullif(btrim(p_name),'') is null then raise exception 'Location name is required'; end if; if p_location_id is null then insert into public.locations(company_id,location_code,name,status,address_line1,city,state_code,postal_code,market_name,area_name) values(p_company_id,upper(btrim(p_location_code)),btrim(p_name),'active',nullif(btrim(p_address),''),nullif(btrim(p_city),''),upper(nullif(btrim(p_state),'')),nullif(btrim(p_postal),''),nullif(btrim(p_market),''),nullif(btrim(p_area),'')) returning id into v_id; else update public.locations set location_code=upper(btrim(p_location_code)),name=btrim(p_name),address_line1=nullif(btrim(p_address),''),city=nullif(btrim(p_city),''),state_code=upper(nullif(btrim(p_state),'')),postal_code=nullif(btrim(p_postal),''),market_name=nullif(btrim(p_market),''),area_name=nullif(btrim(p_area),''),updated_at=now() where id=p_location_id and company_id=p_company_id returning id into v_id; if v_id is null then raise exception 'Location not found'; end if; end if; select count(*) into v_count from public.locations where company_id=p_company_id and status='active'; insert into public.company_settings(company_id,organization_mode) values(p_company_id,case when v_count>1 then 'multi_site' else 'single_site' end) on conflict(company_id) do update set organization_mode=excluded.organization_mode,updated_at=now(); insert into private.operator_audit_events(request_id,actor_user_id,company_id,action,target_type,target_id,after_json) values(p_request_id,p_actor_user_id,p_company_id,case when p_location_id is null then 'customer.location_created' else 'customer.location_updated' end,'location',v_id,jsonb_build_object('location_code',upper(btrim(p_location_code)),'name',btrim(p_name),'active_location_count',v_count)) on conflict(request_id) do nothing; return jsonb_build_object('location_id',v_id,'active_location_count',v_count,'organization_mode',case when v_count>1 then 'multi_site' else 'single_site' end); end $function$;
revoke all on function public.operator_service_upsert_location(uuid,uuid,uuid,text,text,text,text,text,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.operator_service_upsert_location(uuid,uuid,uuid,text,text,text,text,text,text,text,text,uuid) to service_role;